// Limpieza determinista del HTML para Blogger
function cerrarEtiquetas(h) {
  const vacias = /^(br|hr|img|input|meta|link|source|wbr|col)$/i;
  const pila = [];
  const salida = h.replace(/<(\/?)([a-zA-Z][a-zA-Z0-9]*)\b[^>]*?(\/?)>/g, (m, cierre, tag, auto) => {
    tag = tag.toLowerCase();
    if (vacias.test(tag) || auto) return m;
    if (!cierre) {
      // un <li> o <p> nuevo cierra el anterior que quedó abierto
      if ((tag === 'li' || tag === 'p') && pila[pila.length - 1] === tag) { pila.pop(); pila.push(tag); return `</${tag}>` + m; }
      pila.push(tag); return m;
    }
    const i = pila.lastIndexOf(tag);
    if (i === -1) return ''; // cierre huérfano
    const abiertasDentro = pila.splice(i).reverse().slice(0, -1);
    return abiertasDentro.map(t => `</${t}>`).join('') + m;
  });
  return salida + pila.reverse().map(t => `</${t}>`).join('');
}
function limpiarHTML(html) {
  let h = String(html || '');
  h = h.replace(/```(?:html|json)?/gi, '');
  h = h.replace(/\\n/g, ' ').replace(/\\"/g, '"');
  h = h.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F​-‍﻿�]/g, '');
  h = h.replace(/<!DOCTYPE[^>]*>/gi, '').replace(/<\/?(html|head|body|meta|title)\b[^>]*>/gi, '');
  h = h.replace(/<style[\s\S]*?<\/style>/gi, '');
  h = h.replace(/<script(?![^>]*application\/ld\+json)[^>]*>[\s\S]*?<\/script>/gi, '');
  h = h.replace(/<h1\b([^>]*)>([\s\S]*?)<\/h1>/gi, '<h2$1>$2</h2>');
  h = h.replace(/\*\*([^*<>]+)\*\*/g, '<strong>$1</strong>');
  h = h.replace(/(^|>)\s*#{2,4}\s+([^<]+)/g, '$1<h3>$2</h3>');
  h = h.replace(/&amp;(nbsp|amp|quot|lt|gt|#\d+);/g, '&$1;');
  h = h.replace(/<[^>]+>/g, tag => tag.replace(/[“”„″]/g, '"').replace(/[‘’]/g, "'"));
  h = h.replace(/<p\b[^>]*>\s*(&nbsp;|<br\s*\/?>)?\s*<\/p>/gi, '');
  h = cerrarEtiquetas(h);
  return h.replace(/\s+/g, ' ').trim();
}
// ============================================================
// Code VALIDATE - limpia el HTML del artículo sin IA y prepara un resumen corto para el validador
// ============================================================
const item = $input.first().json;
let html = item.output || item.text || item.response || item.html || '';
if (!html && item.messages) {
  const lastMsg = item.messages[item.messages.length - 1];
  if (lastMsg && lastMsg.content) html = lastMsg.content;
}
if (!html || html.trim().length === 0) {
  html = `<p style="color:#c0392b; font-weight:bold;">⚠️ Error: No se pudo generar el contenido del artículo. Revisa la conexión con DeepSeek y el prompt del AI Agent.</p><p>Tema esperado: ${item.emailSubject || 'Sin título'}</p>`;
}
html = limpiarHTML(html);
// El banner oficial del Club de Huroneros se inserta más adelante: se quitan los enlaces sueltos a WhatsApp
html = html
  .replace(/<a\b[^>]*chat\.whatsapp\.com[^>]*>[\s\S]*?<\/a>/gi, '')
  .replace(/https?:\/\/chat\.whatsapp\.com\/\S+/gi, '')
  .replace(/<p\b[^>]*>[^<]*Comunidad de WhatsApp Veterinaria[\s\S]*?<\/p>/gi, '');
const titulos = [...html.matchAll(/<h[23]\b[^>]*>([\s\S]*?)<\/h[23]>/gi)].map(m => m[1].replace(/<[^>]+>/g, '').trim());
const tieneFAQ = /preguntas\s+frecuentes|faq/i.test(titulos.join(' '));
const palabras = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<[^>]+>/g, ' ').split(/\s+/).filter(Boolean).length;
return [{ html, titulos: titulos.slice(0, 25), tieneFAQ, palabras }];

// 🖼️ Image Injector (Pexels) - HURONES con alt dinámico según el artículo
const articleData = $('Prepare Blogger Content').first().json;
let html = articleData.emailBody || articleData.CONTENIDO || "";
const keyword = articleData.emailSubject || articleData.TEMA_ARTICULO || "ferret pet";
const tituloArticulo = articleData.emailSubject || articleData.TEMA_ARTICULO || "Hurón";
let enrichedHtml = html;

// ====== FALLBACK: imágenes de hurones subidas a Blogger (URLs únicas) ======
const FALLBACK_IMAGES = [
  {
    src: 'https://blogger.googleusercontent.com/img/a/AVvXsEi7xNNNSJPtz6djoVM6Pj4tZbkoZdSxDJr1MTeH5pc_nZ2dsqa5ZMRh-ppHI6TC03aMr2Ns57OP6krhpG2TC-E_N9DrinYPOxHNtrAKtOwPFby8SlEeeWa0TOnD0yld9zp3NOe7KIwg9G1RW9NcrlSbr2RYNHVq3cFpF_tvTPt20Py4s5DKP1HcG7Dka9A'
