// ====== Generador de HTML para una imagen con alt dinámico ======
function makeImg(src, alt, photographer = 'Blogger', photographer_url = '') {
  // Escapar comillas dobles en alt
  const altEscaped = alt.replace(/"/g, '');
  return `<figure style="margin:24px 0;text-align:center">
    <img src="${src}" alt="${altEscaped}" style="max-width:100%;height:auto;border-radius:10px;box-shadow:0 4px 12px rgba(0,0,0,.15)" loading="lazy"/>
    <figcaption style="font-size:12px;color:#777;margin-top:6px">Foto de ${photographer}${photographer_url ? ' en <a href="'+photographer_url+'" target="_blank" rel="nofollow">'+photographer+'</a>' : ''}</figcaption>
  </figure>`;
}

// ====== Sinónimos para buscar en Pexels ======
const searchTerms = [
  'domestic ferret',
  'ferret pet',
  'ferret',
  'mustela putorius furo',
  'hurón doméstico',
  'hurón',
  'ferret playing',
  'ferret sleeping'
];

// ====== Función para obtener imágenes de Pexels ======
async function fetchPexelsImages() {
  const API_KEY = "***ENMASCARADO***";
  const perPage = 3;
  for (const term of searchTerms) {
    try {
      const url = `https://api.pexels.com/v1/search?query=${encodeURIComponent(term)}&per_page=${perPage}&orientation=landscape`;
      const res = await fetch(url, { headers: { Authorization: API_KEY } });
      if (!res.ok) continue;
      const data = await res.json();
      if (data.photos && data.photos.length > 0) {
        const photos = data.photos.slice(0, 2);
        return photos.map(p => ({
          src: p.src.large2x || p.src.large,
          alt: p.alt || term,
          photographer: p.photographer || 'Pexels',
          photographer_url: p.photographer_url || 'https://www.pexels.com'
        }));
      }
    } catch (e) {
      continue;
    }
  }
  return null;
}

// ====== Insertar imagen en posición estratégica ======
function insertImage(html, imgHtml, position = 'after_first_h2') {
  if (position === 'after_first_h2') {
    const idx = html.indexOf('</h2>');
    if (idx !== -1) {
      return html.slice(0, idx + 5) + imgHtml + html.slice(idx + 5);
    } else {
      return imgHtml + html;
    }
  } else if (position === 'after_second_h2') {
    let idx = html.indexOf('</h2>');
    if (idx !== -1) {
      idx = html.indexOf('</h2>', idx + 1);
      if (idx !== -1) {
        return html.slice(0, idx + 5) + imgHtml + html.slice(idx + 5);
      }
    }
    return insertImage(html, imgHtml, 'after_first_h2');
  } else {
    return insertImage(html, imgHtml, 'after_first_h2');
  }
}

// ====== Construir alt dinámico basado en el título del artículo ======
function generarAlt(tema) {
  // Extraer palabras clave del título (máximo 5 palabras)
  const palabras = tema.split(' ').slice(0, 5).join(' ');
  // Frases predefinidas para dar contexto
  const frases = [
    `Hurón - ${palabras} (imagen ilustrativa)`,
    `Hurón mostrando signos relacionados con ${palabras.toLowerCase()}`,
    `Fotografía de un hurón en contexto de ${palabras.toLowerCase()}`
  ];
  // Elegir una aleatoriamente para variar
  const idx = Math.floor(Math.random() * frases.length);
  return frases[idx];
}

// ====== OBTENER IMÁGENES ======
let images = [];
try {
  const pexelsImages = await fetchPexelsImages();
  if (pexelsImages && pexelsImages.length > 0) {
    images = pexelsImages;
  } else {
    // Fallback: usar imágenes de Blogger (elegir 2 aleatorias)
    const shuffled = FALLBACK_IMAGES.sort(() => 0.5 - Math.random());
    images = shuffled.slice(0, 2).map(img => ({
      src: img.src,
      alt: generarAlt(tituloArticulo), // 🔥 alt dinámico basado en el título
      photographer: 'Blogger',
      photographer_url: ''
    }));
  }
} catch (e) {
  const shuffled = FALLBACK_IMAGES.sort(() => 0.5 - Math.random());
  images = shuffled.slice(0, 2).map(img => ({
    src: img.src,
    alt: generarAlt(tituloArticulo),
    photographer: 'Blogger',
    photographer_url: ''
  }));
}

// Si las imágenes son de Pexels y su alt es genérico, mejoramos con el título
images = images.map(img => {
  // Si el alt es muy corto o genérico, lo reemplazamos por uno más descriptivo
  if (!img.alt || img.alt.length < 10 || img.alt.toLowerCase().includes('pexels')) {
    img.alt = generarAlt(tituloArticulo);
  }
  return img;
});

// ====== INSERTAR IMÁGENES EN EL HTML ======
if (images.length > 0) {
  const img1Html = makeImg(images[0].src, images[0].alt, images[0].photographer, images[0].photographer_url);
  enrichedHtml = insertImage(enrichedHtml, img1Html, 'after_first_h2');
}
if (images.length > 1) {
  const img2Html = makeImg(images[1].src, images[1].alt, images[1].photographer, images[1].photographer_url);
  enrichedHtml = insertImage(enrichedHtml, img2Html, 'after_second_h2');
}

// ====== INSERTAR CATÁLOGO DE AFILIADOS ======
let catalogoHtml = '';
try {
  const agentOut = $('Agente Catálogo Afiliados Hurones').first()?.json;
  let out = agentOut?.output || agentOut?.text || '';
  if (typeof out !== 'string') out = '';
  catalogoHtml = out.replace(/```html/gi, '').replace(/```/g, '').trim();
} catch (e) {}

if (catalogoHtml) {
  enrichedHtml = enrichedHtml + '<hr style="margin:30px 0;border:0;border-top:1px solid #eee;">' + catalogoHtml;
}

// ====== SALIDA ======
return [{ json: { ...articleData, emailBody: enrichedHtml, CONTENIDO: enrichedHtml, imagesAdded: images.length } }];

// ============================================================
// FILTRAR CASOS RELEVANTES PARA HURONES (un solo artículo)
// ============================================================

const allItems = $input.all().map(i => i.json);

// --- Detectar el artículo (el primer elemento que tenga emailSubject o TITULO) ---
let article = allItems.find(item =>
    (item.emailSubject || item.TITULO) && !item['Título (Narrativa)']
);

// Si no se encontró, intentar con cualquier elemento que tenga KEYWORD_PRINCIPAL
if (!article) {
    article = allItems.find(item =>
        item.KEYWORD_PRINCIPAL && !item['Título (Narrativa)']
    );
}

// Fallback: usar el primer elemento que no sea claramente un caso
if (!article) {
    article = allItems.find(item => !item.ID);
}

// Si no hay artículo, salir
if (!article) {
    return [];
}

// --- Detectar todos los casos clínicos ---
const allCases = allItems.filter(item =>
    item.ID && item['Título (Narrativa)']
);

// Función para normalizar texto y buscar especies
function contieneHurones(texto) {
    if (!texto) return false;
    const normalizado = texto
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase();
    return normalizado.includes('huron') || normalizado.includes('hurón');
}

// --- Filtrar SOLO casos de hurones ---
const casosHurones = allCases.filter(c => {
    // Revisar campos clave donde pueda aparecer la especie
    const campos = [
        c['Título (Narrativa)'],
        c['Motivo de consulta'],
        c['Anamnesis'],
        c['Exploración física'],
        c['Diagnóstico definitivo'],
        c['Especie'],
        c['Animal'],
        c['Raza'],
        c['Palabras Clave (SEO)'],
        c['Asignación a Artículo Base']
    ].filter(Boolean);

    // Si algún campo menciona "hurón", lo incluimos
    return campos.some(campo => contieneHurones(campo));
});

// --- Filtrar adicionalmente: EXCLUIR casos que mencionen perros/gatos ---
const casosHuronesFiltrados = casosHurones.filter(c => {
    const campos = [
        c['Título (Narrativa)'],
        c['Motivo de consulta'],
        c['Anamnesis'],
        c['Diagnóstico definitivo']
    ].filter(Boolean);

    // Si menciona perro o gato, lo excluimos (a menos que también mencione hurón)
    const tienePerro = campos.some(t => /perro|canino|dog/i.test(t));
    const tieneGato = campos.some(t => /gato|felino|cat/i.test(t));

    // Permitimos solo si NO tiene perro/gato, o si tiene hurón Y también perro/gato (pero mejor priorizar hurón puro)
    return !tienePerro && !tieneGato;
});

// Si no hay casos de hurones, devolvemos el artículo sin casos
if (casosHuronesFiltrados.length === 0) {
    return [{
        json: {
            ...article,
            casosDisponibles: [],
            totalCasosFiltrados: 0,
            mensaje: 'No se encontraron casos clínicos de hurones para este tema.'
        }
    }];
}

// --- Filtrar casos por coincidencia con el TÍTULO del artículo ---
const tituloArticulo = (article.TITULO || article.emailSubject || '').toLowerCase();
const keywordPrincipal = (article.KEYWORD_PRINCIPAL || '').toLowerCase();
const cluster = (article.CLUSTER || '').toLowerCase();
const textoBusqueda = `${tituloArticulo} ${keywordPrincipal} ${cluster}`.trim();

let casosRelevantes = casosHuronesFiltrados;

if (textoBusqueda) {
    const palabras = textoBusqueda.split(/\s+/).filter(p => p.length > 3);

    casosRelevantes = casosHuronesFiltrados.filter(c => {
        const textoCaso = [
            c['Título (Narrativa)'],
            c['Motivo de consulta'],
            c['Anamnesis'],
            c['Exploración física'],
            c['Diagnóstico definitivo'],
            c['Palabras Clave (SEO)']
        ].filter(Boolean).join(' ').toLowerCase();

        return palabras.some(p => textoCaso.includes(p));
    });

    // Si no hay coincidencias con palabras clave, tomar los primeros 5 hurones
    if (casosRelevantes.length === 0) {
        casosRelevantes = casosHuronesFiltrados.slice(0, 3);
    }
} else {
    // Si no hay texto de búsqueda, tomar los primeros 5 hurones
    casosRelevantes = casosHuronesFiltrados.slice(0, 3);
}

// Limitar a un máximo de 5 casos (para no saturar el prompt)
if (casosRelevantes.length > 3) {
    casosRelevantes = casosRelevantes.slice(0, 3);
}

// --- Construir el resumen de casos ---
const casesSummary = casosRelevantes.map(c => ({
    ID: c.ID || '',
    TITULO: c['Título (Narrativa)'] || '',
    MOTIVO: c['Motivo de consulta'] || '',
    ANAMNESIS: c['Anamnesis'] || '',
    EXPLORACION: c['Exploración física'] || '',
    PRUEBAS: c['Pruebas complementarias'] || '',
    DIAGNOSTICO_DIF: c['Diagnóstico diferencial'] || '',
    DIAGNOSTICO_DEF: c['Diagnóstico definitivo'] || '',
    TRATAMIENTO: c['Tratamiento (con nexo al artículo)'] || '',
    EVOLUCION: c['Evolución'] || '',
    KEYWORDS: c['Palabras Clave (SEO)'] || '',
    ASIGNACION: c['Asignación a Artículo Base'] || '',
    ESTATUS: c['Estatus'] || '',
    FICHA_VENTA: c['Ficha de venta'] || ''
}));

// Recorta cada campo de los casos para no inflar el prompt del agente de casos
const corto = (t, n = 300) => { t = String(t || ''); return t.length > n ? t.slice(0, n) + '…' : t; };
for (const c of casesSummary) for (const k of Object.keys(c)) c[k] = corto(c[k]);

// --- Devolver UN SOLO resultado (el artículo enriquecido) ---
return [{
    json: {
        ...article,
        casosDisponibles: casesSummary,
        totalCasosFiltrados: casesSummary.length,
        mensaje: casesSummary.length > 0 ?
            `Se encontraron ${casesSummary.length} casos clínicos de hurones para este tema.` :
            'No se encontraron casos clínicos de hurones para este tema.'
    }
}];

// ============================================================
// FUSIONAR DATOS DEL CASO CLÍNICO (fix: el AI Agent solo devuelve 'output'
// y descarta emailSubject/emailBody/ID_UNICO/CLUSTER/PILAR del artículo)
// ============================================================
const originalItems = $('🔧 Preparar casos para IA').all();
const agentItems = $input.all();

const resultados = [];
for (let i = 0; i < agentItems.length; i++) {
  const original = originalItems[i] ? originalItems[i].json : {};
  const agent = agentItems[i].json;

  resultados.push({
    json: {
      ...original,      // TITULO, emailSubject, emailBody, ID_UNICO, CLUSTER, PILAR, etc.
      output: agent.output   // JSON con el caso clínico generado
    }
  });
}

return resultados;

// ============================================================
// INSERTAR CASO EN EL ARTÍCULO
// Recibe el artículo y la respuesta del agente (JSON)
// ============================================================

const items = $input.all();
const resultados = [];

for (const item of items) {
  let articleHtml = item.json.emailBody || item.json.CONTENIDO || '';

  // Parsear la respuesta del agente (asumiendo que está en item.json.output)
  let caseData = null;
  try {
    caseData = JSON.parse(String(item.json.output || '{}').replace(/```json/gi, '').replace(/```/g, '').trim() || '{}');
  } catch (e) {
    caseData = null;
  }

  // Si no hay datos válidos, dejar el artículo sin cambios
  if (!caseData || !caseData.htmlBlock) {
    resultados.push(item);
    continue;
  }

  const block = caseData.htmlBlock;
  const position = caseData.insertPosition || 'despues_segundo_parrafo';

  // Función para insertar después de un punto específico
  function insertAfter(html, marker, block) {
    const index = html.indexOf(marker);
    if (index === -1) return html;
    return html.slice(0, index + marker.length) + block + html.slice(index + marker.length);
  }

  let newHtml = articleHtml;

  switch (position) {
    case 'inicio':
      // Después del primer párrafo
      const firstP = newHtml.indexOf('</p>');
      if (firstP !== -1) {
        newHtml = newHtml.slice(0, firstP + 4) + block + newHtml.slice(firstP + 4);
      }
      break;
    case 'despues_segundo_parrafo':
      let secondP = newHtml.indexOf('</p>');
      if (secondP !== -1) {
        secondP = newHtml.indexOf('</p>', secondP + 1);
        if (secondP !== -1) {
          newHtml = newHtml.slice(0, secondP + 4) + block + newHtml.slice(secondP + 4);
        }
      }
      break;
    case 'despues_beneficios':
      // Buscar un H2 que contenga "Beneficios" o "Ventajas"
      const benefRegex = /<h2[^>]*>.*?Beneficios.*?<\/h2>/i;
      const matchBenef = newHtml.match(benefRegex);
      if (matchBenef) {
        const endTag = matchBenef[0].length + matchBenef.index;
        newHtml = newHtml.slice(0, endTag) + block + newHtml.slice(endTag);
      }
      break;
    case 'antes_faq':
      const faqIndex = newHtml.indexOf('<h3');
      if (faqIndex !== -1) {
        newHtml = newHtml.slice(0, faqIndex) + block + newHtml.slice(faqIndex);
      }
      break;
    case 'final':
      const descargoIndex = newHtml.lastIndexOf('<p style="font-size: 12px;');
      if (descargoIndex !== -1) {
        newHtml = newHtml.slice(0, descargoIndex) + block + newHtml.slice(descargoIndex);
      } else {
        newHtml = newHtml + block;
      }
      break;
    default:
      // Por defecto, después del segundo párrafo
      let p2 = newHtml.indexOf('</p>');
      if (p2 !== -1) {
        p2 = newHtml.indexOf('</p>', p2 + 1);
        if (p2 !== -1) {
          newHtml = newHtml.slice(0, p2 + 4) + block + newHtml.slice(p2 + 4);
        }
      }
  }

  resultados.push({
    json: {
      ...item.json,
      emailBody: newHtml,
      CONTENIDO: newHtml,
      casoInsertado: true,
      caseId: caseData.selectedCaseId || ''
    }
  });
}

return resultados;

// PROGRAMAR 2 ARTÍCULOS POR SEMANA A DISTINTA HORA
// ==============================================================================
// CONFIGURACIÓN DE PUBLICACIÓN
// ==============================================================================

// ELIGE EL MODO:
// "LUN_MIE_VIE"  -> Publica Lunes (1), Miércoles (3) y Viernes (5)
// "DOS_SEMANA"   -> Publica 2 artículos por semana (Martes y Jueves) a horas distintas
const MODO_PUBLICACION = "DOS_SEMANA";   // ← cámbialo aquí según necesites

// Días según el modo elegido (0 = Domingo, 1 = Lunes, ..., 6 = Sábado)
let diasPublicacion = [];
if (MODO_PUBLICACION === "LUN_MIE_VIE") {
  diasPublicacion = [1, 3, 5]; // Lunes, Miércoles, Viernes
} else if (MODO_PUBLICACION === "DOS_SEMANA") {
  diasPublicacion = [2, 4];    // Martes y Jueves
} else {
  diasPublicacion = [2, 5];    // Por defecto: Martes y Viernes
}

// Horarios variados (Formato 24h)
const horasPosibles = [8, 10, 14, 17, 19, 21];
const minutosPosibles = [0, 15, 30, 45];

// ==============================================================================
// LÓGICA DE CÁLCULO DE FECHAS
// ==============================================================================

const index = $itemIndex; // Índice del artículo actual (0, 1, 2...)

// Generador pseudo-aleatorio determinista (misma hora para el mismo artículo)
function pseudoRandom(seed) {
  const x = Math.sin(seed + 1) * 10000;
  return x - Math.floor(x);
}

// Calcula la fecha de publicación para este artículo
function obtenerFechaPublicacion(numeroArticulo) {
  // Empezamos desde HOY (no desde el mes siguiente)
  let fechaActual = new Date();
  fechaActual.setHours(0, 0, 0, 0); // empezamos desde las 00:00 de hoy

  let articulosContados = 0;
  const MAX_ITERACIONES = 365 * 2; // seguridad (máximo 2 años)
  let iteraciones = 0;

  while (iteraciones < MAX_ITERACIONES) {
    const diaSemanaActual = fechaActual.getDay();

    // Solo cuenta los días de publicación configurados
    if (diasPublicacion.includes(diaSemanaActual)) {
      if (articulosContados === numeroArticulo) {
        // Asignar hora y minuto únicos y consistentes
        const randHoraIndex = Math.floor(pseudoRandom(numeroArticulo * 7) * horasPosibles.length);
        const randMinIndex  = Math.floor(pseudoRandom(numeroArticulo * 13) * minutosPosibles.length);

        const horaElegida   = horasPosibles[randHoraIndex];
        const minutoElegido = minutosPosibles[randMinIndex];

        fechaActual.setHours(horaElegida, minutoElegido, 0, 0);
        return fechaActual;
      }
      articulosContados++;
    }

    // Avanzar siempre un día
    fechaActual.setDate(fechaActual.getDate() + 1);
    iteraciones++;
  }

  // Fallback (no debería llegar aquí)
  return new Date();
}

