// ====== Función para obtener imágenes de Pexels ======
async function fetchPexelsImages() {
  const API_KEY = "***ENMASCARADO***";
  const perPage = 3;
  for (const term of searchTerms) {
    try {
      const url = `https://api.pexels.com/v1/search?query=${encodeURIComponent(term)}&per_page=${perPage}&orientation=landscape`;
      const res = await fetch(url, { headers: { Authorization: API_KEY } });
      if (!res.ok) continue;
      const data = await res.json();
      if (data.photos && data.photos.length > 0) {
        const photos = data.photos.slice(0, 2);
        return photos.map(p => ({
          src: p.src.large2x || p.src.large,
          alt: p.alt || term,
          photographer: p.photographer || 'Pexels',
          photographer_url: p.photographer_url || 'https://www.pexels.com'
        }));
      }
    } catch (e) {
      continue;
    }
  }
  return null;
}

// ====== Insertar imagen en posición estratégica ======
function insertImage(html, imgHtml, position = 'after_first_h2') {
  if (position === 'after_first_h2') {
    const idx = html.indexOf('</h2>');
    if (idx !== -1) {
      return html.slice(0, idx + 5) + imgHtml + html.slice(idx + 5);
    } else {
      return imgHtml + html;
    }
  } else if (position === 'after_second_h2') {
    let idx = html.indexOf('</h2>');
    if (idx !== -1) {
      idx = html.indexOf('</h2>', idx + 1);
      if (idx !== -1) {
        return html.slice(0, idx + 5) + imgHtml + html.slice(idx + 5);
      }
    }
    return insertImage(html, imgHtml, 'after_first_h2');
  } else {
    return insertImage(html, imgHtml, 'after_first_h2');
  }
}

