}

// --- Filtrar casos por coincidencia con el TÍTULO del artículo ---
const tituloArticulo = (article.TITULO || article.emailSubject || '').toLowerCase();
const keywordPrincipal = (article.KEYWORD_PRINCIPAL || '').toLowerCase();
const cluster = (article.CLUSTER || '').toLowerCase();
const textoBusqueda = `${tituloArticulo} ${keywordPrincipal} ${cluster}`.trim();

