// Recorta cada campo de los casos para no inflar el prompt del agente de casos
const corto = (t, n = 300) => { t = String(t || ''); return t.length > n ? t.slice(0, n) + '…' : t; };
for (const c of casesSummary) for (const k of Object.keys(c)) c[k] = corto(c[k]);

// --- Devolver UN SOLO resultado (el artículo enriquecido) ---
return [{
