    continue;
  }

  const block = caseData.htmlBlock;
  const position = caseData.insertPosition || 'despues_segundo_parrafo';

  // Función para insertar después de un punto específico
  function insertAfter(html, marker, block) {
    const index = html.indexOf(marker);
    if (index === -1) return html;
    return html.slice(0, index + marker.length) + block + html.slice(index + marker.length);
  }

  let newHtml = articleHtml;

  switch (position) {
    case 'inicio':
      // Después del primer párrafo
      const firstP = newHtml.indexOf('</p>');
      if (firstP !== -1) {
        newHtml = newHtml.slice(0, firstP + 4) + block + newHtml.slice(firstP + 4);
      }
      break;
    case 'despues_segundo_parrafo':
      let secondP = newHtml.indexOf('</p>');
      if (secondP !== -1) {
        secondP = newHtml.indexOf('</p>', secondP + 1);
        if (secondP !== -1) {
          newHtml = newHtml.slice(0, secondP + 4) + block + newHtml.slice(secondP + 4);
        }
      }
      break;
    case 'despues_beneficios':
      // Buscar un H2 que contenga "Beneficios" o "Ventajas"
      const benefRegex = /<h2[^>]*>.*?Beneficios.*?<\/h2>/i;
      const matchBenef = newHtml.match(benefRegex);
      if (matchBenef) {
        const endTag = matchBenef[0].length + matchBenef.index;
        newHtml = newHtml.slice(0, endTag) + block + newHtml.slice(endTag);
      }
      break;
    case 'antes_faq':
      const faqIndex = newHtml.indexOf('<h3');
      if (faqIndex !== -1) {
        newHtml = newHtml.slice(0, faqIndex) + block + newHtml.slice(faqIndex);
      }
      break;
    case 'final':
      const descargoIndex = newHtml.lastIndexOf('<p style="font-size: 12px;');
      if (descargoIndex !== -1) {
        newHtml = newHtml.slice(0, descargoIndex) + block + newHtml.slice(descargoIndex);
      } else {
        newHtml = newHtml + block;
      }
      break;
    default:
      // Por defecto, después del segundo párrafo
      let p2 = newHtml.indexOf('</p>');
      if (p2 !== -1) {
        p2 = newHtml.indexOf('</p>', p2 + 1);
        if (p2 !== -1) {
          newHtml = newHtml.slice(0, p2 + 4) + block + newHtml.slice(p2 + 4);
        }
      }
  }

  resultados.push({
    json: {
      ...item.json,
      emailBody: newHtml,
      CONTENIDO: newHtml,
      casoInsertado: true,
      caseId: caseData.selectedCaseId || ''
    }
  });
}

return resultados;

// PROGRAMAR 2 ARTÍCULOS POR SEMANA A DISTINTA HORA
// ==============================================================================
// CONFIGURACIÓN DE PUBLICACIÓN
// ==============================================================================

// ELIGE EL MODO:
// "LUN_MIE_VIE"  -> Publica Lunes (1), Miércoles (3) y Viernes (5)
// "DOS_SEMANA"   -> Publica 2 artículos por semana (Martes y Jueves) a horas distintas
const MODO_PUBLICACION = "DOS_SEMANA";   // ← cámbialo aquí según necesites

// Días según el modo elegido (0 = Domingo, 1 = Lunes, ..., 6 = Sábado)
let diasPublicacion = [];
if (MODO_PUBLICACION === "LUN_MIE_VIE") {
  diasPublicacion = [1, 3, 5]; // Lunes, Miércoles, Viernes
} else if (MODO_PUBLICACION === "DOS_SEMANA") {
  diasPublicacion = [2, 4];    // Martes y Jueves
} else {
  diasPublicacion = [2, 5];    // Por defecto: Martes y Viernes
}

// Horarios variados (Formato 24h)
const horasPosibles = [8, 10, 14, 17, 19, 21];
const minutosPosibles = [0, 15, 30, 45];

// ==============================================================================
// LÓGICA DE CÁLCULO DE FECHAS
// ==============================================================================

const index = $itemIndex; // Índice del artículo actual (0, 1, 2...)

// Generador pseudo-aleatorio determinista (misma hora para el mismo artículo)
function pseudoRandom(seed) {
  const x = Math.sin(seed + 1) * 10000;
  return x - Math.floor(x);
}

// Calcula la fecha de publicación para este artículo
function obtenerFechaPublicacion(numeroArticulo) {
  // Empezamos desde HOY (no desde el mes siguiente)
  let fechaActual = new Date();
  fechaActual.setHours(0, 0, 0, 0); // empezamos desde las 00:00 de hoy

  let articulosContados = 0;
  const MAX_ITERACIONES = 365 * 2; // seguridad (máximo 2 años)
  let iteraciones = 0;

  while (iteraciones < MAX_ITERACIONES) {
    const diaSemanaActual = fechaActual.getDay();

    // Solo cuenta los días de publicación configurados
    if (diasPublicacion.includes(diaSemanaActual)) {
      if (articulosContados === numeroArticulo) {
        // Asignar hora y minuto únicos y consistentes
        const randHoraIndex = Math.floor(pseudoRandom(numeroArticulo * 7) * horasPosibles.length);
        const randMinIndex  = Math.floor(pseudoRandom(numeroArticulo * 13) * minutosPosibles.length);

        const horaElegida   = horasPosibles[randHoraIndex];
        const minutoElegido = minutosPosibles[randMinIndex];

        fechaActual.setHours(horaElegida, minutoElegido, 0, 0);
        return fechaActual;
      }
      articulosContados++;
    }

    // Avanzar siempre un día
    fechaActual.setDate(fechaActual.getDate() + 1);
    iteraciones++;
  }

  // Fallback (no debería llegar aquí)
  return new Date();
}

// Obtener fecha calculada para este artículo
const fechaProgramada = obtenerFechaPublicacion(index);

// ==============================================================================
// RETORNO DE DATOS AL SIGUIENTE NODO
// ==============================================================================
return {
  ...$input.item.json, // mantiene todos tus campos originales
  articuloNumero: index + 1,
  fechaPublicacionISO: fechaProgramada.toISOString(),
  fechaPublicacionTexto: fechaProgramada.toLocaleString('es-ES', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  }),
  programadoAno: fechaProgramada.getFullYear(),
  programadoMes: fechaProgramada.getMonth() + 1,
  programadoDia: fechaProgramada.getDate(),
  programadoHora: fechaProgramada.getHours(),
  programadoMinuto: fechaProgramada.getMinutes()
};

